// StoreBillingServiceClient is a client for the arcforges.fleet.v1.StoreBillingService service.
type StoreBillingServiceClient interface {
	// Opaque reference to pass as obfuscatedAccountId when launching a purchase.
	// auth: account session (Android)
	// idempotency: read
	// deadline: 5 s
	// stream: none
	// errors: none (implicit codes only)
	// locality: cloud
	GetPlayAccountReference(context.Context, *v1.StoreBillingServiceGetPlayAccountReferenceRequest) (*v1.StoreBillingServiceGetPlayAccountReferenceResponse, error)
	// Verify a purchase with subscriptionsv2, link it, grant, and acknowledge server-side.
	// auth: account session (Android)
	// idempotency: natural: per purchase token
	// deadline: 20 s
	// stream: none
	// errors: VALIDATION/purchase_invalid, CONFLICT/purchase_already_linked, AUTHORIZATION/account_mismatch, STATE/purchase_pending, EXECUTION/provider_error, RESOURCE/overloaded
	// locality: cloud -> Google Play
	// state: SM-SUBSCRIPTION: (none) -> ACTIVE | PENDING
	SubmitPlayPurchase(context.Context, *v1.StoreBillingServiceSubmitPlayPurchaseRequest) (*v1.StoreBillingServiceSubmitPlayPurchaseResponse, error)
	// Resubmit existing purchases. Purchases without an account reference return NEEDS_CONFIRMATION.
	// auth: account session (Android)
	// idempotency: natural: per purchase token
	// deadline: 30 s
	// stream: none
	// errors: VALIDATION/purchase_invalid, EXECUTION/provider_error
	// locality: cloud -> Google Play
	RestorePlayPurchases(context.Context, *v1.StoreBillingServiceRestorePlayPurchasesRequest) (*v1.StoreBillingServiceRestorePlayPurchasesResponse, error)
	// Link a purchase made outside the app after the user's explicit confirmation.
	// auth: account session (Android) with step-up
	// idempotency: natural
	// deadline: 20 s
	// stream: none
	// errors: STATE/not_found, CONFLICT/purchase_already_linked, AUTHENTICATION/step_up_required
	// locality: cloud
	ConfirmPurchaseLink(context.Context, *v1.StoreBillingServiceConfirmPurchaseLinkRequest) (*v1.StoreBillingServiceConfirmPurchaseLinkResponse, error)
	// Subscriptions from all sources, the effective plan and duplicate warnings.
	// auth: account session
	// idempotency: read
	// deadline: 5 s
	// stream: none
	// errors: none (implicit codes only)
	// locality: cloud
	GetBillingStatus(context.Context, *v1.StoreBillingServiceGetBillingStatusRequest) (*v1.StoreBillingServiceGetBillingStatusResponse, error)
}

